    28→    /// Active requests for 1 or more columns each
    29→    active_batch_columns_requests:
    30→        FnvHashMap<DataColumnsByRootRequestId, ActiveBatchColumnsRequest>,
    31→    peer_attempts: HashMap<PeerId, usize>,
    32→    /// Set of peers that claim to have imported this block and their custody columns
    33→    lookup_peers: Arc<RwLock<HashSet<PeerId>>>,
    34→    /// Span for tracing the lifetime of this request.
    35→    span: Span,
    36→    _phantom: PhantomData<T>,
    37→}
    38→
    39→#[derive(Debug, Eq, PartialEq)]
    40→pub enum Error {
    41→    SendFailed(&'static str),
    42→    TooManyFailures,
    43→    BadState(String),
    44→    NoPeer(ColumnIndex),
    45→    /// Received a download result for a different request id than the in-flight request.
    46→    /// There should only exist a single request at a time. Having multiple requests is a bug and
    47→    /// can result in undefined state, so it's treated as a hard error and the lookup is dropped.
    48→    UnexpectedRequestId {
    49→        expected_req_id: DataColumnsByRootRequestId,
    50→        req_id: DataColumnsByRootRequestId,
    51→    },
    52→}
    53→
    54→struct ActiveBatchColumnsRequest {
    55→    indices: Vec<ColumnIndex>,
    56→    /// Span for tracing the lifetime of this request.
    57→    span: Span,
    58→}
    59→
    60→pub type CustodyRequestResult<E> =
    61→    Result<Option<(DataColumnSidecarList<E>, PeerGroup, Duration)>, Error>;
    62→
    63→impl<T: BeaconChainTypes> ActiveCustodyRequest<T> {
    64→    pub(crate) fn new(
    65→        block_root: Hash256,
    66→        custody_id: CustodyId,
    67→        column_indices: &[ColumnIndex],
    68→        lookup_peers: Arc<RwLock<HashSet<PeerId>>>,
    69→    ) -> Self {
    70→        let span = debug_span!(
    71→            parent: Span::current(),
    72→            SPAN_OUTGOING_CUSTODY_REQUEST,
    73→            %block_root,
    74→        );
    75→        Self {
    76→            block_root,
    77→            custody_id,
    78→            column_requests: HashMap::from_iter(
    79→                column_indices
    80→                    .iter()
    81→                    .map(|index| (*index, ColumnRequest::new())),
    82→            ),
    83→            active_batch_columns_requests: <_>::default(),
    84→            peer_attempts: HashMap::new(),
    85→            lookup_peers,
    86→            span,
    87→            _phantom: PhantomData,
    88→        }
    89→    }
    90→
    91→    /// Insert a downloaded column into an active custody request. Then make progress on the
    92→    /// entire request.
    93→    ///
    94→    /// ### Returns
    95→    ///
    96→    /// - `Err`: Custody request has failed and will be dropped
    97→    /// - `Ok(Some)`: Custody request has successfully completed and will be dropped
    98→    /// - `Ok(None)`: Custody request still active
    99→    pub(crate) fn on_data_column_downloaded(
   100→        &mut self,
   101→        peer_id: PeerId,
   102→        req_id: DataColumnsByRootRequestId,
   103→        resp: RpcResponseResult<DataColumnSidecarList<T::EthSpec>>,
   104→        cx: &mut SyncNetworkContext<T>,
   105→    ) -> CustodyRequestResult<T::EthSpec> {
   106→        let Some(batch_request) = self.active_batch_columns_requests.get_mut(&req_id) else {
   107→            warn!(
   108→                block_root = ?self.block_root,
   109→                %req_id,
   110→                "Received custody column response for unrequested index"
   111→            );
   112→            return Ok(None);
   113→        };
   114→
   115→        let _guard = batch_request.span.clone().entered();
   116→
   117→        match resp {
   118→            Ok((data_columns, seen_timestamp)) => {
   119→                debug!(
   120→                    block_root = ?self.block_root,
   121→                    %req_id,
   122→                    %peer_id,
   123→                    count = data_columns.len(),
   124→                    "Custody column download success"
   125→                );
   126→
   127→                // Map columns by index as an optimization to not loop the returned list on each
   128→                // requested index. The worse case is 128 loops over a 128 item vec + mutation to
   129→                // drop the consumed columns.
   130→                let mut data_columns = HashMap::<ColumnIndex, _>::from_iter(
   131→                    data_columns.into_iter().map(|d| (d.index, d)),
   132→                );
   133→                // Accumulate columns that the peer does not have to issue a single log per request
   134→                let mut missing_column_indexes = vec![];
   135→
   136→                for column_index in &batch_request.indices {
   137→                    let column_request = self
   138→                        .column_requests
   139→                        .get_mut(column_index)
   140→                        .ok_or(Error::BadState("unknown column_index".to_owned()))?;
   141→
   142→                    if let Some(data_column) = data_columns.remove(column_index) {
   143→                        column_request.on_download_success(
   144→                            req_id,
   145→                            peer_id,
   146→                            data_column,
   147→                            seen_timestamp,
   148→                        )?;
   149→                    } else {
   150→                        // Peer does not have the requested data.
   151→                        // TODO(das) do not consider this case a success. We know for sure the block has
   152→                        // data. However we allow the peer to return empty as we can't attribute fault.
   153→                        // TODO(das): Should track which columns are missing and eventually give up
   154→                        // TODO(das): If the peer is in the lookup peer set it claims to have imported
   155→                        // the block AND its custody columns. So in this case we can downscore
   156→                        column_request.on_download_error(req_id)?;
   157→                        missing_column_indexes.push(column_index);
   158→                    }
   159→                }
   160→
   161→                // Note: no need to check data_columns is empty, SyncNetworkContext ensures that
   162→                // successful responses only contain requested data.
   163→
   164→                if !missing_column_indexes.is_empty() {
   165→                    // Note: Batch logging that columns are missing to not spam logger
   166→                    debug!(
   167→                        block_root = ?self.block_root,
   168→                        %req_id,
   169→                        %peer_id,
   170→                        ?missing_column_indexes,
   171→                        "Custody column peer claims to not have some data"
   172→                    );
   173→                }
   174→            }
   175→            Err(err) => {
   176→                debug!(
   177→                    block_root = ?self.block_root,
   178→                    %req_id,
   179→                   %peer_id,
   180→                   error = ?err,
   181→                    "Custody column download error"
   182→                );
   183→
   184→                // TODO(das): Should mark peer as failed and try from another peer
   185→                for column_index in &batch_request.indices {
   186→                    self.column_requests
   187→                        .get_mut(column_index)
   188→                        .ok_or(Error::BadState("unknown column_index".to_owned()))?
   189→                        .on_download_error_and_mark_failure(req_id)?;
   190→                }
   191→            }
   192→        };
   193→
   194→        self.continue_requests(cx)
   195→    }
   196→
   197→    pub(crate) fn continue_requests(
   198→        &mut self,
   199→        cx: &mut SyncNetworkContext<T>,
   200→    ) -> CustodyRequestResult<T::EthSpec> {
   201→        let _guard = self.span.clone().entered();
   202→        if self.column_requests.values().all(|r| r.is_downloaded()) {
   203→            // All requests have completed successfully.
   204→            let mut peers = HashMap::<PeerId, Vec<usize>>::new();
   205→            let mut seen_timestamps = vec![];
   206→            let columns = std::mem::take(&mut self.column_requests)
   207→                .into_values()
   208→                .map(|request| {
   209→                    let (peer, data_column, seen_timestamp) = request.complete()?;
   210→                    peers
   211→                        .entry(peer)
   212→                        .or_default()
   213→                        .push(data_column.index as usize);
   214→                    seen_timestamps.push(seen_timestamp);
   215→                    Ok(data_column)
   216→                })
   217→                .collect::<Result<Vec<_>, _>>()?;
   218→
   219→            let peer_group = PeerGroup::from_set(peers);
   220→            let max_seen_timestamp = seen_timestamps.into_iter().max().unwrap_or(timestamp_now());
   221→            return Ok(Some((columns, peer_group, max_seen_timestamp)));
   222→        }
   223→
   224→        let active_request_count_by_peer = cx.active_request_count_by_peer();
   225→        let mut columns_to_request_by_peer = HashMap::<PeerId, Vec<ColumnIndex>>::new();
   226→        let lookup_peers = self.lookup_peers.read();
   227→        // Create deterministic hasher per request to ensure consistent peer ordering within
   228→        // this request (avoiding fragmentation) while varying selection across different requests
   229→        let random_state = RandomState::new();
   230→
   231→        for (column_index, request) in self.column_requests.iter() {
   232→            if let Some(wait_duration) = request.is_awaiting_download() {
   233→                // Note: an empty response is considered a successful response, so we may end up
   234→                // retrying many more times than `MAX_CUSTODY_COLUMN_DOWNLOAD_ATTEMPTS`.
   235→                if request.download_failures > MAX_CUSTODY_COLUMN_DOWNLOAD_ATTEMPTS {
   236→                    return Err(Error::TooManyFailures);
   237→                }
   238→
   239→                let peer_to_request = self.select_column_peer(
   240→                    cx,
   241→                    &active_request_count_by_peer,
   242→                    &lookup_peers,
   243→                    *column_index,
   244→                    &random_state,
   245→                );
   246→
   247→                if let Some(peer_id) = peer_to_request {
   248→                    columns_to_request_by_peer
   249→                        .entry(peer_id)
   250→                        .or_default()
   251→                        .push(*column_index);
   252→                } else if wait_duration > MAX_STALE_NO_PEERS_DURATION {
   253→                    // Allow to request to sit stale in `NotStarted` state for at most
   254→                    // `MAX_STALE_NO_PEERS_DURATION`, else error and drop the request. Note that
   255→                    // lookup will naturally retry when other peers send us attestations for
   256→                    // descendants of this un-available lookup.
   257→                    return Err(Error::NoPeer(*column_index));
   258→                } else {
   259→                    // Do not issue requests if there is no custody peer on this column
   260→                }
   261→            }
   262→        }
   263→
   264→        let peer_requests = columns_to_request_by_peer.len();
   265→        if peer_requests > 0 {
   266→            let columns_requested_count = columns_to_request_by_peer
   267→                .values()
   268→                .map(|v| v.len())
   269→                .sum::<usize>();
   270→            debug!(
   271→                lookup_peers = lookup_peers.len(),
   272→                "Requesting {} columns from {} peers", columns_requested_count, peer_requests,
   273→            );
   274→        } else {
   275→            debug!(
   276→                lookup_peers = lookup_peers.len(),
   277→                "No column peers found for look up",
   278→            );
   279→        }
   280→
   281→        for (peer_id, indices) in columns_to_request_by_peer.into_iter() {
   282→            let request_result = cx
   283→                .data_column_lookup_request(
   284→                    DataColumnsByRootRequester::Custody(self.custody_id),
   285→                    peer_id,
   286→                    DataColumnsByRootSingleBlockRequest {
   287→                        block_root: self.block_root,
   288→                        indices: indices.clone(),
   289→                    },
   290→                    // If peer is in the lookup peer set, it claims to have imported the block and
   291→                    // must have its columns in custody. In that case, set `true = enforce max_requests`
   292→                    // and downscore if data_columns_by_root does not returned the expected custody
   293→                    // columns. For the rest of peers, don't downscore if columns are missing.
   294→                    lookup_peers.contains(&peer_id),
   295→                )
   296→                .map_err(Error::SendFailed)?;
   297→
   298→            match request_result {
   299→                LookupRequestResult::RequestSent(req_id) => {
   300→                    *self.peer_attempts.entry(peer_id).or_insert(0) += 1;
   301→
   302→                    let client = cx.network_globals().client(&peer_id).kind;
   303→                    let batch_columns_req_span = debug_span!(
   304→                        "batch_columns_req",
   305→                        %peer_id,
   306→                        %client,
   307→                    );
   308→                    let _guard = batch_columns_req_span.clone().entered();
   309→                    for column_index in &indices {
   310→                        let column_request = self
   311→                            .column_requests
   312→                            .get_mut(column_index)
   313→                            // Should never happen: column_index is iterated from column_requests
   314→                            .ok_or(Error::BadState("unknown column_index".to_owned()))?;
   315→
   316→                        column_request.on_download_start(req_id)?;
   317→                    }
   318→
   319→                    self.active_batch_columns_requests.insert(
   320→                        req_id,
   321→                        ActiveBatchColumnsRequest {
   322→                            indices,
   323→                            span: batch_columns_req_span,
   324→                        },
   325→                    );
   326→                }
   327→                LookupRequestResult::NoRequestNeeded(_) => unreachable!(),
   328→                LookupRequestResult::Pending(_) => unreachable!(),
   329→            }
   330→        }
   331→
   332→        Ok(None)
   333→    }
   334→
   335→    fn select_column_peer(
   336→        &self,
   337→        cx: &mut SyncNetworkContext<T>,
   338→        active_request_count_by_peer: &HashMap<PeerId, usize>,
   339→        lookup_peers: &HashSet<PeerId>,
   340→        column_index: ColumnIndex,
   341→        random_state: &RandomState,
   342→    ) -> Option<PeerId> {
   343→        // We draw from the total set of peers, but prioritize those peers who we have
   344→        // received an attestation or a block from (`lookup_peers`), as the `lookup_peers` may take
   345→        // time to build up and we are likely to not find any column peers initially.
   346→        let custodial_peers = cx.get_custodial_peers(column_index);
   347→        let mut prioritized_peers = custodial_peers
   348→            .iter()
   349→            .filter(|peer| {
   350→                // Exclude peers that we have already made too many attempts to.
   351→                self.peer_attempts.get(peer).copied().unwrap_or(0) <= MAX_CUSTODY_PEER_ATTEMPTS
   352→            })
   353→            .map(|peer| {
   354→                (
   355→                    // Prioritize peers that claim to know have imported this block
   356→                    if lookup_peers.contains(peer) { 0 } else { 1 },
   357→                    // De-prioritize peers that we have already attempted to download from
   358→                    self.peer_attempts.get(peer).copied().unwrap_or(0),
   359→                    // Prefer peers with fewer requests to load balance across peers.
   360→                    active_request_count_by_peer.get(peer).copied().unwrap_or(0),
   361→                    // The hash ensures consistent peer ordering within this request
   362→                    // to avoid fragmentation while varying selection across different requests.
   363→                    random_state.hash_one(peer),
   364→                    *peer,
   365→                )
   366→            })
   367→            .collect::<Vec<_>>();
   368→        prioritized_peers.sort_unstable();
   369→
   370→        prioritized_peers
   371→            .first()
   372→            .map(|(_, _, _, _, peer_id)| *peer_id)
   373→    }
   374→}
   375→
   376→/// TODO(das): this attempt count is nested into the existing lookup request count.
   377→const MAX_CUSTODY_COLUMN_DOWNLOAD_ATTEMPTS: usize = 3;
   378→
   379→/// Max number of attempts to request custody columns from a single peer.
   380→const MAX_CUSTODY_PEER_ATTEMPTS: usize = 3;
   381→
   382→struct ColumnRequest<E: EthSpec> {
   383→    status: Status<E>,
   384→    download_failures: usize,
   385→}
   386→
   387→#[derive(Debug, Clone)]
   388→enum Status<E: EthSpec> {
   389→    NotStarted(Instant),
   390→    Downloading(DataColumnsByRootRequestId),
   391→    Downloaded(PeerId, Arc<DataColumnSidecar<E>>, Duration),
   392→}
   393→
   394→impl<E: EthSpec> ColumnRequest<E> {
   395→    fn new() -> Self {
   396→        Self {
   397→            status: Status::NotStarted(Instant::now()),
   398→            download_failures: 0,
   399→        }
   400→    }
   401→
   402→    fn is_awaiting_download(&self) -> Option<Duration> {
   403→        match self.status {
   404→            Status::NotStarted(start_time) => Some(start_time.elapsed()),
   405→            Status::Downloading { .. } | Status::Downloaded { .. } => None,
   406→        }
   407→    }
   408→
   409→    fn is_downloaded(&self) -> bool {
   410→        match self.status {
   411→            Status::NotStarted { .. } | Status::Downloading { .. } => false,
   412→            Status::Downloaded { .. } => true,
   413→        }
   414→    }
   415→
   416→    fn on_download_start(&mut self, req_id: DataColumnsByRootRequestId) -> Result<(), Error> {
   417→        match &self.status {
   418→            Status::NotStarted { .. } => {
   419→                self.status = Status::Downloading(req_id);
   420→                Ok(())
   421→            }
   422→            other => Err(Error::BadState(format!(
   423→                "bad state on_download_start expected NotStarted got {other:?}"
   424→            ))),
   425→        }
   426→    }
   427→
   428→    fn on_download_error(&mut self, req_id: DataColumnsByRootRequestId) -> Result<(), Error> {
   429→        match &self.status {
   430→            Status::Downloading(expected_req_id) => {
   431→                if req_id != *expected_req_id {
   432→                    return Err(Error::UnexpectedRequestId {
   433→                        expected_req_id: *expected_req_id,
   434→                        req_id,
   435→                    });
   436→                }
   437→                self.status = Status::NotStarted(Instant::now());
   438→                Ok(())
   439→            }
   440→            other => Err(Error::BadState(format!(
   441→                "bad state on_download_error expected Downloading got {other:?}"
   442→            ))),
   443→        }
   444→    }
   445→
   446→    fn on_download_error_and_mark_failure(
   447→        &mut self,
   448→        req_id: DataColumnsByRootRequestId,
   449→    ) -> Result<(), Error> {
   450→        // TODO(das): Should track which peers don't have data
   451→        self.download_failures += 1;
   452→        self.on_download_error(req_id)
   453→    }
   454→
   455→    fn on_download_success(
   456→        &mut self,
   457→        req_id: DataColumnsByRootRequestId,
   458→        peer_id: PeerId,
   459→        data_column: Arc<DataColumnSidecar<E>>,
   460→        seen_timestamp: Duration,
   461→    ) -> Result<(), Error> {
   462→        match &self.status {
   463→            Status::Downloading(expected_req_id) => {
   464→                if req_id != *expected_req_id {
   465→                    return Err(Error::UnexpectedRequestId {
   466→                        expected_req_id: *expected_req_id,
   467→                        req_id,
   468→                    });
   469→                }
   470→                self.status = Status::Downloaded(peer_id, data_column, seen_timestamp);
   471→                Ok(())
   472→            }
   473→            other => Err(Error::BadState(format!(
   474→                "bad state on_download_success expected Downloading got {other:?}"
   475→            ))),
   476→        }
   477→    }
   478→
   479→    fn complete(self) -> Result<(PeerId, Arc<DataColumnSidecar<E>>, Duration), Error> {
   480→        match self.status {
   481→            Status::Downloaded(peer_id, data_column, seen_timestamp) => {
   482→                Ok((peer_id, data_column, seen_timestamp))
   483→            }
   484→            other => Err(Error::BadState(format!(
   485→                "bad state complete expected Downloaded got {other:?}"
   486→            ))),
   487→        }
   488→    }
   489→}
   490→

