    68→impl gossipsub::DataTransform for SnappyTransform {
    69→    // Provides the snappy decompression from RawGossipsubMessages
    70→    fn inbound_transform(
    71→        &self,
    72→        raw_message: gossipsub::RawMessage,
    73→    ) -> Result<gossipsub::Message, std::io::Error> {
    74→        // first check the size of the compressed payload
    75→        if raw_message.data.len() > self.max_compressed_len {
    76→            return Err(Error::new(
    77→                ErrorKind::InvalidData,
    78→                "ssz_snappy encoded data > max_compressed_len",
    79→            ));
    80→        }
    81→        // check the length of the uncompressed bytes
    82→        let len = decompress_len(&raw_message.data)?;
    83→        if len > self.max_uncompressed_len {
    84→            return Err(Error::new(
    85→                ErrorKind::InvalidData,
    86→                "ssz_snappy decoded data > MAX_PAYLOAD_SIZE",
    87→            ));
    88→        }
    89→
    90→        let mut decoder = Decoder::new();
    91→        let decompressed_data = decoder.decompress_vec(&raw_message.data)?;
    92→
    93→        // Build the GossipsubMessage struct
    94→        Ok(gossipsub::Message {
    95→            source: raw_message.source,
    96→            data: decompressed_data,
    97→            sequence_number: raw_message.sequence_number,
    98→            topic: raw_message.topic,
    99→        })
   100→    }
